$ErrorActionPreference = "Stop"

$repoRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
$file = Join-Path $repoRoot "TombEngine\Renderer\RendererSprites.cpp"

if (-not (Test-Path $file)) {
    throw "RendererSprites.cpp was not found at: $file"
}

$utf8 = [System.Text.UTF8Encoding]::new($false)
$old = $utf8.GetString([System.Convert]::FromBase64String(""))
$new = $utf8.GetString([System.Convert]::FromBase64String(""))
$content = [System.IO.File]::ReadAllText($file)

$matches = ([regex]::Matches($content, [regex]::Escape($old))).Count
if ($matches -ne 1) {
    throw "Expected exactly one current DrawSpriteSorted block, found $matches. No file was changed."
}

$content = $content.Replace($old, $new)
[System.IO.File]::WriteAllText($file, $content, $utf8)

Write-Host "RendererSprites.cpp updated successfully."
